const fs = require('fs');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  const scan = async (label) => {
    const results = await page.evaluate(async () => await axe.run());
    const violations = results.violations.filter(v => !v.tags.includes('best-practice'));
    if (violations.length) {
      console.log(label + ': ' + JSON.stringify(violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))));
      process.exitCode = 1;
    } else {
      console.log(label + ': ok');
    }
  };

  await scan('initial');

  await page.click('button[type="submit"]');
  const activeId = await page.evaluate(() => document.activeElement && document.activeElement.id);
  const errorText = await page.locator('#fullName-error').textContent();
  const errorVisible = await page.locator('#fullName-error').isVisible();
  console.log(JSON.stringify({ activeId, errorText, errorVisible }));
  if (activeId !== 'fullName' || !errorVisible || !errorText?.includes('required')) {
    throw new Error('Validation state did not focus/announce the first invalid field');
  }

  await scan('invalid-state');

  await page.fill('#fullName', 'Jordan Lee');
  await page.fill('#email', 'jordan@example.com');
  await page.fill('#phone', '+1 (555) 123-4567');
  await page.click('button[type="submit"]');
  const status = await page.locator('#form-status').textContent();
  console.log(JSON.stringify({ status }));
  if (!status || !status.includes('ready to send')) {
    throw new Error('Success status not shown');
  }

  await scan('success-state');
  await browser.close();
})().catch(err => {
  console.error(err);
  process.exit(1);
});
