   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="root"></div>

     <script>
       function fieldMarkup({ id, label, type, autocomplete, help, required = false, inputMode = '', wide = false }) {
         const requiredMark = required
           ? '<span class="required-indicator" aria-hidden="true">*</span><span class="sr-only"> required</span>'
           : '';

         return `
           <div class="form-field${wide ? ' form-field--wide' : ''}">
             <label for="${id}">${label}${requiredMark}</label>
             <input
               id="${id}"
               name="${id}"
               type="${type}"
               ${required ? 'required' : ''}
               autocomplete="${autocomplete}"
               ${inputMode ? `inputmode="${inputMode}"` : ''}
               aria-describedby="${id}-help"
             >
             <p class="field-help" id="${id}-help">${help}</p>
             <p class="field-error" id="${id}-error" hidden></p>
           </div>
         `;
       }

       function SupportForm() {
         return `
           <header class="page-shell">
             <div class="brand" aria-label="Northstar Support">
               <span class="brand-mark" aria-hidden="true">NS</span>
               <span>Northstar Support</span>
             </div>
           </header>
           <main id="maincontent" tabindex="-1" class="page-shell">
             <section class="hero" aria-labelledby="page-title">
               <h1 id="page-title">Contact support</h1>
               <p class="lede">Tell us what you need help with and we’ll route your message to the right team.</p>
             </section>

             <section class="card" aria-labelledby="form-title">
               <h2 id="form-title" class="sr-only">Support contact form</h2>
               <form id="support-form" novalidate>
                 <div class="form-grid">
                   ${fieldMarkup({
                     id: 'fullName',
                     label: 'Full name',
                     type: 'text',
                     autocomplete: 'name',
                     required: true,
                     help: 'Enter the name you want us to use when we reply.',
                     wide: true
                   })}
                   ${fieldMarkup({
                     id: 'email',
                     label: 'Email address',
                     type: 'email',
                     autocomplete: 'email',
                     required: true,
                     help: 'We’ll send your support reply to this address.',
                     wide: true
                   })}
                   ${fieldMarkup({
                     id: 'phone',
                     label: 'Phone number',
                     type: 'tel',
                     autocomplete: 'tel',
                     help: 'Optional. Use digits with spaces, dashes, or parentheses, for example +1 (555) 123-4567.',
                     inputMode: 'tel',
                     wide: true
                   })}
                 </div>

                 <div class="actions">
                   <button type="submit">Send message</button>
                   <p class="status" id="form-status" role="status" aria-atomic="true"></p>
                 </div>
               </form>
             </section>
           </main>
         `;
       }

       document.getElementById('root').innerHTML = SupportForm();

       const form = document.getElementById('support-form');
       const status = document.getElementById('form-status');
       const fields = [
         {
           id: 'fullName',
           label: 'Full name',
           required: true,
           validate: value => {
             if (!value.trim()) return 'Error: Full name is required.';
             return '';
           }
         },
         {
           id: 'email',
           label: 'Email address',
           required: true,
           validate: value => {
             if (!value.trim()) return 'Error: Email address is required.';
             const emailInput = document.getElementById('email');
             if (!emailInput.checkValidity()) {
               return 'Error: Enter a valid email address, like name@example.com.';
             }
             return '';
           }
         },
         {
           id: 'phone',
           label: 'Phone number',
           required: false,
           validate: value => {
             const trimmed = value.trim();
             if (!trimmed) return '';
             const allowed = /^[+]?[\d\s().-]+$/.test(trimmed);
             const digits = trimmed.replace(/\D/g, '').length;
             if (!allowed || digits < 7 || digits > 15) {
               return 'Error: Enter a phone number using digits, spaces, dashes, or parentheses.';
             }
             return '';
           }
         }
       ];

       function setFieldState(field, message) {
         const input = document.getElementById(field.id);
         const error = document.getElementById(`${field.id}-error`);
         const helpId = `${field.id}-help`;

         if (message) {
           input.setAttribute('aria-invalid', 'true');
           input.setAttribute('aria-describedby', `${helpId} ${error.id}`);
           error.textContent = message;
           error.hidden = false;
         } else {
           input.removeAttribute('aria-invalid');
           input.setAttribute('aria-describedby', helpId);
           error.textContent = '';
           error.hidden = true;
         }
       }

       function validateField(field) {
         const input = document.getElementById(field.id);
         const message = field.validate(input.value);
         setFieldState(field, message);
         return message;
       }

       function validateForm() {
         const messages = fields.map(field => ({ field, message: validateField(field) }));
         return messages.filter(item => item.message);
       }

       fields.forEach(field => {
         const input = document.getElementById(field.id);
         let touched = false;

         input.addEventListener('blur', () => {
           touched = true;
           validateField(field);
         });

         input.addEventListener('input', () => {
           if (touched) validateField(field);
         });
       });

       form.addEventListener('submit', event => {
         event.preventDefault();
         status.textContent = '';
         status.classList.remove('is-success');

         const invalidFields = validateForm();
         if (invalidFields.length) {
           const firstInvalid = document.getElementById(invalidFields[0].field.id);
           firstInvalid.focus();
           return;
         }

         status.textContent = 'Message ready to send. Thanks for reaching out.';
         status.classList.add('is-success');
         form.reset();
         fields.forEach(field => setFieldState(field, ''));
       });
     </script>
   </body>
 </html>

