const fs = require('fs');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  const run = async (label) => {
    const results = await page.evaluate(async () => await window.axe.run());
    const violations = results.violations.filter(v => !v.tags.includes('best-practice'));
    console.log(label + ':' + JSON.stringify(violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))));
    return violations;
  };

  const initial = await run('initial');
  await page.click('button[type="submit"]');
  const focused = await page.evaluate(() => document.activeElement && document.activeElement.id);
  const firstError = await page.locator('#fullName-error').textContent();
  console.log(JSON.stringify({ focused, firstError }));
  const invalid = await run('invalid');
  await page.fill('#fullName', 'Avery Quinn');
  await page.fill('#email', 'avery@example.com');
  await page.fill('#phone', '+1 (555) 123-4567');
  await page.click('button[type="submit"]');
  const status = await page.locator('#form-status').textContent();
  console.log(JSON.stringify({ status }));
  const success = await run('success');
  await browser.close();

  if (initial.length || invalid.length || success.length || focused !== 'fullName' || !firstError || !firstError.includes('required') || !status || !status.includes('ready to send')) {
    process.exit(1);
  }
})();
